    Justify::Center,
    Justify::End,
    Justify::Between,
]
.map(|justify| {
    let name = match justify {
        Justify::Start => "Justify::Start",
        Justify::Center => "Justify::Center",
        Justify::End => "Justify::End",
        _ => "Justify::Between",
