use navree::ui::{Flag, flag, flags};

// A constant, completed by your editor:
Flag::new(flags::AE)

// The code as a person writes it, checked while your app compiles:
flag!("gb-sct")

// A code that comes from data: any case, and an unknown code draws a placeholder.
Flag::country(code)

// A code that comes from data: any case, `gb-sct` or `GB_SCT`. One no flag
// has draws a neutral placeholder, and never panics.
let codes = ["us", "GB-SCT", "xx-unknown"];
Row::gap(4).children(
    codes
        .iter()
        .map(|code| Flag::country(code).size(FlagSize::Lg))
        .collect::<Vec<_>>(),
)
